#include <iostream>
#include <vector>
#include <stack>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int L, C;
    if (!(cin >> L >> C)) return 0;

    vector<vector<int>> A(L, vector<int>(C));
    for (int i = 0; i < L; ++i) {
        for (int j = 0; j < C; ++j) {
            cin >> A[i][j];
        }
    }

    int n = L - 1;
    int m = C - 1;
    vector<vector<int>> B(n, vector<int>(m, 0));

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (A[i][j] + A[i + 1][j + 1] <= A[i][j + 1] + A[i + 1][j]) {
                B[i][j] = 1;
            }
        }
    }

    vector<int> H(m, 0);
    int max_elements = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (B[i][j] == 1) {
                H[j]++;
            } else {
                H[j] = 0;
            }
        }

        stack<int> s;
        for (int j = 0; j <= m; ++j) {
            int current_h = (j == m) ? 0 : H[j];
            while (!s.empty() && H[s.top()] >= current_h) {
                int h = H[s.top()];
                s.pop();
                if (h > 0) {
                    int w = s.empty() ? j : (j - s.top() - 1);
                    int elements = (h + 1) * (w + 1);
                    if (elements > max_elements) {
                        max_elements = elements;
                    }
                }
            }
            s.push(j);
        }
    }

    cout << max_elements << "\n";

    return 0;
}
